output_text:
[
  {
    "id": "must_take_entry_cart",
    "text": "A shopper must take the entry cart before doing the shopping trip, even if only a small number of items is needed.",
    "abstraction": {
      "state_properties": {
        "entry_cart_rack": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "take_entry_cart": {
          "pre": {
            "and": [
              "entry_cart_rack",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entry_cart"
    }
  },
  {
    "id": "return_cart_to_front_bay",
    "text": "Before leaving the supermarket, the shopper must return the cart to the front-left cart return bay.",
    "abstraction": {
      "state_properties": {
        "front_cart_return_bay": "at(0,1)",
        "cart_parked_in_front_bay": "cartAt(0,1)"
      },
      "events": {
        "return_cart_to_front_bay": {
          "pre": {
            "and": [
              "front_cart_return_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_front_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "return_cart_to_front_bay"
    }
  },
  {
    "id": "only_leave_cart_at_return_bay",
    "text": "A cart may only be left in the designated front-left cart return bay, not abandoned in shopping aisles or near the exit.",
    "abstraction": {
      "state_properties": {
        "front_cart_return_bay": "at(0,1)"
      },
      "events": {
        "leave_cart": {
          "pre": "LEAVE_CART",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "leave_cart",
          {
            "not": "front_cart_return_bay"
          }
        ]
      }
    }
  },
  {
    "id": "exit_only_after_cart_returned",
    "text": "A shopper is forbidden to exit until the cart is parked in the front return bay.",
    "abstraction": {
      "state_properties": {
        "cart_parked_in_front_bay": "cartAt(0,1)"
      },
      "events": {
        "attempt_exit": {
          "pre": "EXIT",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "attempt_exit",
          {
            "not": "cart_parked_in_front_bay"
          }
        ]
      }
    }
  },
  {
    "id": "no_hand_carrying_merchandise",
    "text": "Merchandise should not be carried by hand; items must be placed directly into a cart when picked up.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull",
        "using_cart": "hasCart"
      },
      "events": {
        "pickup_item_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "using_cart"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "carrying_item_by_hand",
          "pickup_item_without_cart"
        ]
      }
    }
  },
  {
    "id": "no_carts_in_lower_middle_aisle",
    "text": "The lower middle aisle is a pedestrian-only or congestion-sensitive zone where carts are not allowed.",
    "abstraction": {
      "state_properties": {
        "lower_middle_aisle": {
          "or": [
            "at(3,5)",
            "at(4,5)",
            "at(5,5)",
            "at(6,5)",
            "at(7,5)"
          ]
        },
        "with_cart": "hasCart"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "with_cart",
          "lower_middle_aisle"
        ]
      }
    }
  },
  {
    "id": "no_carts_on_exit_side",
    "text": "Carts are not allowed on the far-right exit side of the store, so shoppers must park the cart before crossing into that area.",
    "abstraction": {
      "state_properties": {
        "exit_side": {
          "or": [
            "at(7,0)",
            "at(7,1)",
            "at(7,2)",
            "at(7,3)",
            "at(7,4)",
            "at(7,5)",
            "at(8,0)",
            "at(8,1)",
            "at(8,2)",
            "at(8,3)",
            "at(8,4)",
            "at(8,5)",
            "at(9,0)",
            "at(9,1)",
            "at(9,2)",
            "at(9,3)",
            "at(9,4)",
            "at(9,5)"
          ]
        },
        "with_cart": "hasCart"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "with_cart",
          "exit_side"
        ]
      }
    }
  },
  {
    "id": "pickup_only_from_authorized_shelf_faces",
    "text": "Items may only be picked from authorized shelf-facing pickup positions, and only while the shopper has a cart.",
    "abstraction": {
      "state_properties": {
        "authorized_pickup_position": {
          "or": [
            "at(1,3)",
            "at(2,2)",
            "at(2,4)",
            "at(3,2)",
            "at(3,4)",
            "at(5,2)",
            "at(5,4)",
            "at(6,2)",
            "at(6,4)"
          ]
        },
        "with_cart": "hasCart"
      },
      "events": {
        "authorized_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "with_cart",
              "authorized_pickup_position"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "PICKUP_ITEM",
          {
            "not": "authorized_item_pickup"
          }
        ]
      }
    }
  }
]
